import {createMaintenance} from './maintenance-state.js?v=expansion15';
import {createTycoon,useItem,install,joinClan,addClanMember,startCase,CASES,makeAuction,bidAuction,openPosition,listOrder,startWar,awardLoot} from './tycoon-state.js?v=expansion15';
export const SERVER_CHECKPOINTS=[['start','Начало / поиск кабеля'],['cable','Взять кабель'],['connect','Кабель в руке / подключить'],['reboot-a','Перезапустить сервер A'],['reboot-b','Перезапустить сервер B'],['power','Отключить питание'],['drawer','Выдвинуть лоток'],['ssd-pickup','Взять SSD со стола'],['ssd-install','SSD в руке / установить'],['ram-pickup','Взять RAM со стола'],['ram-install','RAM в руке / установить'],['close','Оба компонента установлены / закрыть'],['boot','Закрытый лоток / включить сервер']];
export function serverCheckpoint(id){const state=createMaintenance();let camera=[0,1.65,6],yaw=0,pitch=-.08,carry=null;if(!SERVER_CHECKPOINTS.some(c=>c[0]===id))throw Error('Неизвестный этап серверной');if(id==='cable'){camera=[-1.35,1.65,2.5];pitch=-.55;}if(id==='connect'){camera=[4.5,1.65,-2.5];carry='cable';pitch=-.12;}if(!['start','cable','connect'].includes(id)){state.network=true;if(id.startsWith('reboot-')){camera=[id==='reboot-a'?-2.8:2.8,1.65,-16.1];pitch=-.12;if(id==='reboot-b')state.restarted=['A'];}else{state.restarted=['A','B'];camera=[1.5,1.65,-31.7];pitch=.22;if(id!=='power'){state.powered=false;camera=[2.5,1.65,-31.9];pitch=-.22;}if(!['power','drawer','boot'].includes(id))state.drawer='open';if(['ssd-pickup','ram-pickup'].includes(id)){camera=[id==='ssd-pickup'?-3.4:-2.2,1.65,-26.7];pitch=-.4;}if(id==='ssd-install'){camera=[3.05,1.65,-31.2];carry='ssd';pitch=-.2;}if(id==='ram-install'){camera=[2.2,1.65,-31.2];carry='ram';pitch=-.2;}if(['ram-pickup','ram-install'].includes(id))state.installed=['ssd'];if(['close','boot'].includes(id))state.installed=['ssd','ram'];if(id==='close')pitch=-.68;if(id==='boot'){camera=[1.5,1.65,-31.7];pitch=.22;}}}return {state,camera,yaw,pitch,carry};}
export function adminCompany({cash=100000,trophies=5000,profession='frontend'}={}){const s=createTycoon('Компания / демонстрация');s.cash=Math.max(0,Math.min(1e12,Number(cash)||0));s.profession=profession;s.area=80;s.inventory={ssd:4,ram:4,cpu:2,gpu:2,monitor:2,chair:2,sqm:5,junior:8,senior:3,admin:3,hacker:3};s.cash+=1000;useItem(s,'senior');useItem(s,'admin');install(s,'ssd');install(s,'ram');joinClan(s,'Центр Инвест / демо');for(let i=0;i<7;i++)addClanMember(s);s.clan.trophies=Math.max(0,Math.min(100000,Number(trophies)||0));s.speed=0;s.cash=Math.max(0,Math.min(1e12,Number(cash)||0));return s;}

export function preparedCompany(action,options={}){const s=adminCompany(options),cash=s.cash;s.cash+=100000;if(action==='case-running'||action==='case-finish'){startCase(s,'audit');s.jobs[0].progress=action==='case-running'?170:339.5;if(action==='case-finish')s.speed=1;}if(action==='auction-bid'||action==='auction-finish'){makeAuction(s,'gpu');if(action==='auction-finish'){bidAuction(s);s.auction.until=s.time+5;s.auction.nextNpc=s.time+10;s.speed=1;}}if(action==='position-close'){openPosition(s,'ssd','long',1000,3);s.prices.ssd*=1.04;}if(action==='own-order')listOrder(s,'ssd','sell',1,Math.ceil(s.prices.ssd*1.15));if(action==='war-running'){startWar(s);s.war.until=s.time+10;s.speed=1;}if(action==='hardware'){s.installed['cpu-15']=1;s.installed['gpu-20']=1;}if(action==='loot')awardLoot(s);s.cash=cash;return s;}
